def powerful_integers(x, y, bound):
 answer=set();a=1
 while a<=bound:
  b=1
  while a+b<=bound:
   answer.add(a+b)
   if y==1:break
   b*=y
  if x==1:break
  a*=x
 return sorted(answer)

